window.futvizVista("edad","<div class=\"rx-mount\" data-rx=\"edad\" data-rx-id=\"edad\" style=\"min-height:420px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"edad\"]={\"id\":\"edad\",\"titulo\":\"Edad\",\"bajada\":\"Qu\u00e9 parte de los minutos de su club juega cada edad: mediana y rango t\u00edpico, por posici\u00f3n.\",\"pregunta\":\"\u00bfCu\u00e1nto juegan los j\u00f3venes y a qu\u00e9 edad se juega m\u00e1s?\",\"tabla\":\"edad\",\"queMirar\":\"La l\u00ednea es la **mediana** y la franja el **rango t\u00edpico** (percentil 25 a 75): la mitad de los jugadores de esa edad cae dentro. Las barras de abajo cuentan los jugador-temporadas de cada edad: donde son pocos, la l\u00ednea se mueve m\u00e1s. Los minutos dependen del equipo y del entrenador, no solo del jugador.\",\"fuente\":\"Understat y FBref\",\"posiciones\":[{\"id\":\"campo\",\"etiqueta\":\"Jugadores de campo\"},{\"id\":\"Portero\",\"etiqueta\":\"Portero\"},{\"id\":\"Defensa\",\"etiqueta\":\"Defensa\"},{\"id\":\"Medio\",\"etiqueta\":\"Medio\"},{\"id\":\"Delantero\",\"etiqueta\":\"Delantero\"}],\"edades\":[17,38]};</script>");